{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Vismodegib, a lipophilic heteroaromatic benzamide with solubility-limited absorption, has an absolute oral bioavailability of 31.8% in humans after a 150 mg dose, exceeding the 20% threshold and supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Fenofibrate, the highest-similarity analogue, is practically insoluble in water yet has approximately 30% oral bioavailability in humans, showing that poor solubility/high lipophilicity does not preclude F>=20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Belumosudil, an oral heteroaromatic amide-type drug, has an absolute bioavailability of 64% in humans after a 200 mg dose, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Sorafenib, a lipophilic kinase inhibitor with solubility challenges, has an absolute oral bioavailability of 38-49% in patients, supporting F>=20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A sorafenib review reports limited oral bioavailability of approximately 8.5%, which would be below the threshold; however, this is contradicted by absolute bioavailability studies reporting 38-49% and is less direct.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Most experimental evidence, including absolute human bioavailability values for vismodegib (31.8%), fenofibrate (~30%), belumosudil (64%), and sorafenib (38-49%), supports F>=20% for this lipophilic, poorly soluble heteroaromatic amide. The single low sorafenib estimate (~8.5%) is outweighed by direct absolute bioavailability studies and low structural transferability.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "All evidence analogues have low Morgan similarity (<0.26), limiting structural transferability.",
    "Sorafenib bioavailability reports are conflicting (8.5% vs 38-49%), and formulation/food effects are not fully controlled.",
    "No query-specific solubility, permeability, or first-pass metabolism data are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

